using Astronomy.MediaFactory.Core.KnowledgeFoundation; using Astronomy.MediaFactory.Core.KnowledgeFoundation.Query; using Astronomy.MediaFactory.Core.KnowledgeFoundation.TypedDomains; using Xunit;
namespace Astronomy.MediaFactory.Tests.KnowledgeFoundation.Query;
public sealed class AstronomyKnowledgeStatementQueryTests{[Fact]public void Default_query_has_default_page_order_and_fingerprint(){var q=new AstronomyKnowledgeStatementQuery();Assert.Equal(AstronomyKnowledgeQueryPage.Default,q.Page);Assert.Equal(new[]{AstronomyKnowledgeStatementSortField.Id,AstronomyKnowledgeStatementSortField.Revision},q.Ordering.Select(o=>o.Field));Assert.Equal(64,q.Fingerprint.Value.Length);}[Fact]public void Filters_are_copied_and_normalized(){var ids=new List<KnowledgeId>{KnowledgeId.Create("z"),KnowledgeId.Create("a")};var q=new AstronomyKnowledgeStatementQuery(statementIds:ids,subjects:new([new("mars")]),domains:new([AstronomyKnowledgeDomain.Physical]),families:new([AstronomyKnowledgePayloadFamily.PhysicalProperty]),knowledgeTypes:new([AstronomyKnowledgeTypeId.Create("x")]),statementKinds:new([KnowledgeStatementKind.Scientific]),statuses:new([KnowledgeFoundationStatus.Approved]),version:new(new KnowledgeVersion(1)),provenance:new(["user"]),page:new(2,3));ids.Add(KnowledgeId.Create("b"));Assert.Equal(new[]{"a","z"},q.StatementIds!.Select(x=>x.Value));Assert.Equal(2,q.Page.Offset);Assert.Throws<NotSupportedException>(()=>((IList<KnowledgeId>)q.StatementIds!).Add(KnowledgeId.Create("x")));}[Fact]public void Input_order_normalizes_same_fingerprint(){var a=new AstronomyKnowledgeStatementQuery(statementIds:[KnowledgeId.Create("b"),KnowledgeId.Create("a")]);var b=new AstronomyKnowledgeStatementQuery(statementIds:[KnowledgeId.Create("a"),KnowledgeId.Create("b")]);Assert.Equal(a.Fingerprint,b.Fingerprint);}[Fact]public void Empty_statement_ids_rejected_and_no_execution_api_exists(){Assert.Throws<ArgumentException>(()=>new AstronomyKnowledgeStatementQuery(statementIds:[]));Assert.DoesNotContain(typeof(AstronomyKnowledgeStatementQuery).GetMethods(),m=>m.Name.Contains("Query")||m.Name.Contains("Execute")||m.Name.Contains("Search"));}}
